nodes.expression:
(
	$structure := reviewed.data.structure;
	$copy := [reviewed.data.copy_review.findings];
	$bugs := [reviewed.data.correctness.findings];
	$where := function($f) { "- `" & $f.path & ($f.line ? ":" & $string($f.line) : "") & "`: " };
	{
		"structure_passed": $structure.passed = true,
		"copy_count": $count($copy),
		"bug_count": $count($bugs),
		"blocking_bugs": $count($filter($bugs, function($f) { $f.severity = "blocking" })),
		"text": $join([
			"### Structure",
			$structure.passed = true ? "The layer and vertical checks pass." : "The layer or vertical checks fail:\n\n```\n" & $structure.report & "\n```",
			"### UI copy",
			$count($copy) = 0 ? "No findings." : $join($map($copy, function($f) { $where($f) & $f.problem & " Try: " & $f.suggestion }), "\n"),
			"### Correctness",
			$count($bugs) = 0 ? "No findings." : $join($map($bugs, function($f) { $where($f) & "(" & $f.severity & ") " & $f.problem }), "\n")
		], "\n\n")
	}
)

nodes.prompt:
A review of a pull request found this:

{{merge.data.text}}

Pick blocking when one finding must be fixed before the merge: a failed structure check, a blocking bug, or a visible string that shows internals. Pick fine when there are no findings, or only small ones. Say why in one sentence.
